/* Qualification only: real server parsers/renderers, no engine or inference. */
#define DS4_SERVER_TEST
#define DS4_SERVER_TEST_NO_MAIN
#include "ds4_server.c"
static char *read_small(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) return NULL;
    char *out = NULL;
    if (!fseek(f, 0, SEEK_END)) {
        long n = ftell(f);
        if (n >= 0 && n <= 1024 * 1024 && !fseek(f, 0, SEEK_SET)) {
            out = calloc((size_t)n + 1, 1);
            if (out && fread(out, 1, (size_t)n, f) != (size_t)n) {
                free(out); out = NULL;
            }
        }
    }
    fclose(f);
    return out;
}
int main(int argc, char **argv) {
    if (argc != 4) return 2;
    char *input = read_small(argv[1]), *tools = read_small(argv[2]);
    char *schemas = NULL, error[256] = {0};
    chat_msgs messages = {0};
    tool_schema_orders orders = {0};
    const char *p = input, *t = tools;
    int result = 1;
    if (input && tools && parse_responses_input(&p, &messages, NULL, NULL, error, sizeof(error)) &&
        parse_tools_value(&t, &schemas, &orders)) {
        ds4_think_mode mode = !strcmp(argv[3], "none") ? DS4_THINK_NONE : DS4_THINK_HIGH;
        char *rendered = render_qwen_chat_prompt_text(&messages, schemas, &orders, mode, mode);
        if (rendered) {
            result = fputs(rendered, stdout) < 0 ? 1 : 0;
            free(rendered);
        }
    } else fprintf(stderr, "prompt parse failed: %s\n", error);
    free(input); free(tools); free(schemas);
    chat_msgs_free(&messages);
    tool_schema_orders_free(&orders);
    return result;
}
